def prime_factors(n):
    factors = set()
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.add(d)
            n //= d
        d += 1
    if n > 1:
        factors.add(n)
    return sorted(factors)

factors = prime_factors(990)
print(f"Prime factors of 990: {factors}")
print(f"Largest prime factor: {max(factors)}")
print(f"Smallest prime factor: {min(factors)}")
print(f"Sum of largest and smallest prime factors: {max(factors) + min(factors)}")

