def to_base7(n):
    """Convert a positive integer to base 7 string."""
    if n == 0:
        return "0"
    digits = []
    while n > 0:
        digits.append(str(n % 7))
        n //= 7
    return ''.join(reversed(digits))

def to_base11(n):
    """Convert a positive integer to base 11 string."""
    if n == 0:
        return "0"
    digits = []
    while n > 0:
        digits.append(str(n % 11))
        n //= 11
    return ''.join(reversed(digits))

# Iterate through all possible values of digits in base 7
# Digits are 0-6. Since it's a 7-digit number (leading digit 0), max value is 6^7
# But actually the pattern is ABC... so leading digit is A, not necessarily 0.
# However, if leading digit is A, then n >= 10^6.
# Let's just iterate through all combinations of 7 digits d6...d0 in base 7
# and check the conditions.

max_n = 0
best_n = None

for d6 in range(7):
    for d5 in range(7):
        for d4 in range(7):
            for d3 in range(7):
                for d2 in range(7):
                    for d1 in range(7):
                        for d0 in range(7):
                            n_base7 = d6*7**6 + d5*7**5 + d4*7**4 + d3*7**3 + d2*7**2 + d1*7**1 + d0
                            n_base11 = d6*11**6 + d5*11**5 + d4*11**4 + d3*11**3 + d2*11**2 + d1*11**1 + d0*11**0

                            # Check base 7 representation
