                                    max_n = n_base11
                                    best_n = n_base11

print(f"Largest n in base 10: {max_n}")
print(f"Best n in base 10: {best_n}")

# Let's also verify by brute force over all possible numbers up to a reasonable limit
# Since we want the largest, let's go up to 10^10 or so
for n in range(1, 10**10 + 1):
    s7 = to_base7(n)
    s11 = to_base11(n)
    if s7 == str(n) and s11 == str(n):
