def count_arrangements(n, g):
    """Count the number of ways to arrange n marbles with g green and n-g red."""
    # This is multinomial coefficient: n! / (g! * (n-g)!)
    from math import factorial
    return factorial(n) // factorial(g) * factorial(n - g)

# Check all possible small values of n and g
valid_solutions = []
for n in range(1, 11):
    for g in range(0, 11):
        if g <= n and n - g <= n - 1:
            # Check the condition
            cond1 = (g**2 + (n-g)**2) == ((n-g)**2)
            cond2 = (g * (n-g)) == ((n-g) * g)
            if cond1 and cond2:
                valid_solutions.append((n, g))

